            # The abundant non-background color outside the key marks the points to expand.
            freq=Counter(v for r,row in enumerate(g) for c,v in enumerate(row)
                         if v!=bg and not (r<3 and 1<=c<4))
            target=freq.most_common(1)[0][0]
            pts=[(r,c) for r in range(h) for c in range(w)
                 if g[r][c]==target and not (r<3 and 1<=c<4)]
            for r,c in pts:
                for dr in range(3):
                    for dc in range(3):
                        rr,cc=r+dr-1,c+dc-1
                        if 0<=rr<h and 0<=cc<w:
                            g[rr][cc]=panel[dr][dc]
            return g
    # Otherwise, a rare marker and the two cells below it define a vertical stamp.
    vals=[v for v in counts if v!=bg]
    target=max(vals,key=lambda v:counts[v])
    candidates=[]
    for r in range(h-2):
        for c in range(w):
            v=g[r][c]
            if v!=bg and v!=target and g[r+1][c]==g[r+2][c]:
                candidates.append((counts[v],r,c))
    _,sr,sc=min(candidates)
